def match(pattern: str, text: str) -> bool:
    """
    Implements a recursive backtracking algorithm for regex matching.
    Supports literal characters, '.', '*', and '+'.
    """

    def is_match(p_index, t_index):
        if p_index == len(pattern) and t_index == len(text):
            return True
        if p_index < len(pattern) and t_index < len(text) and \
           (pattern[p_index] == text[t_index] or pattern[p_index] == '.'):
            return is_match(p_index + 1, t_index + 1)

        if p_index < len(pattern):
            if pattern[p_index] == '*':
                return (is_match(p_index - 1, t_index) or
                        (t_index < len(text) and 
                         (pattern[p_index - 1] == text[t_index] or pattern[p_index - 1] == '.') and
                         is_match(p_index, t_index + 1)))
            elif pattern[p_index] == '+':
                return (t_index < len(text) and 
                        (pattern[p_index - 1] == text[t_index] or pattern[p_index - 1] == '.') and
                        is_match(p_index, t_index + 1)) or \
                       is_match(p_index - 1, t_index)

        if p_index < len(pattern) and pattern[p_index] == '*':
            return is_match(p_index + 1, t_index)

        return False

    return is_match(0, 0)

def match(pattern: str, text: str) -> bool:
    """
    Implements a basic regular expression matching algorithm using recursion
    and memoization. Supports literal characters, '.', '*', and '+'.
    """
    memo = {}

    def dp(p_index: int, t_index: int) -> bool:
        if (p_index, t_index) in memo:
            return memo[(p_index, t_index)]
        if p_index == len(pattern):
            return t_index == len(text)

        first_match = t_index < len(text) and (pattern[p_index] == text[t_index] or pattern[p_index] == '.')

        if p_index + 1 < len(pattern):
            if pattern[p_index + 1] == '*':
                result = (dp(p_index + 2, t_index) or 
                          (first_match and dp(p_index, t_index + 1)))
                memo[(p_index, t_index)] = result
                return result
            elif pattern[p_index + 1] == '+':
                result = first_match and (dp(p_index, t_index + 1) or dp(p_index + 2, t_index))
                memo[(p_index, t_index)] = result
                return result

        if first_match:
            result = dp(p_index + 1, t_index + 1)
            memo[(p_index, t_index)] = result
            return result

        memo[(p_index, t_index)] = False
        return False

    return dp(0, 0)

